        self.f.release();
    }

    /// Score scores a word.
    pub fn score(self: Scorer, arena: Allocator, word: []const u8) f64 {
        var w = Writer.init();
        defer w.deinit();
        w.int(0);
        (&w).string(word);
        return invoke(self.f.id, arena, &w, f64, struct {
            fn read(r: *Reader) Error!f64 {
                return try r.float();
            }
        }.read) catch @panic("Go failed to answer");
