/// Kind is a string enum.
pub const Kind = enum {
    kind_a,
    kind_b,
    kind_c,

    /// The value of the case in Go.
    pub fn value(self: Kind) []const u8 {
        return switch (self) {
            .kind_a => "a",
            .kind_b => "b",
            .kind_c => "c",
        };
    }

    /// The case of a value of Go's.
    pub fn fromValue(v: []const u8) ?Kind {
        if (std.mem.eql(u8, v, "a")) return .kind_a;
        if (std.mem.eql(u8, v, "b")) return .kind_b;
        if (std.mem.eql(u8, v, "c")) return .kind_c;
        return null;
    }
};

/// Level is an integer enum.
pub const Level = enum(i64) {
    low = 1,
    high = 2,

    /// The value of the case in Go.
    pub fn value(self: Level) i64 {
        return @intFromEnum(self);
    }

    /// The case of a value of Go's.
    pub fn fromValue(v: i64) ?Level {
        if (v == 1) return .low;
        if (v == 2) return .high;
        return null;
    }
};

