pub const EchoOnMainF = struct {
    f: *GoFunc,

    /// Keeps the function past the call that gave it, until release.
    pub fn keep(self: EchoOnMainF) EchoOnMainF {
        self.f.retain();
        return self;
    }

    pub fn release(self: EchoOnMainF) void {
        self.f.release();
    }

    /// Calls the function.
    pub fn call(self: EchoOnMainF, p0: Inner) void {
        var w = Writer.init();
        defer w.deinit();
        enc_Inner((&w), p0);
        self.f.notify(&w);
    }
};

/// The errors an implementation returns: those package roundtrip declares, with
/// native.NewError, which Go compares with errors.Is, and the others: see
/// fail and failGo for their messages.
pub const Error = error{ Named, Unsupported, Closed, Canceled, Go, Other, OutOfMemory };

/// The code of an error the module declares.
fn errorCode(e: Error) ?[]const u8 {
    return switch (e) {
        error.Named => "named",
        else => null,
    };
}

fn errorOfCode(code: []const u8) ?Error {
    if (std.mem.eql(u8, code, "named")) return error.Named;
    return null;
}

// The functions Go calls.

export fn mygo_roundtrip_init(cb: Callback, id_base: u64, malloc: Malloc, free: Free) void {
    runtime = .{ .cb = cb, .id_base = id_base, .malloc = malloc, .free = free };
}

export fn mygo_roundtrip_new_Echo(obj: u64, args: ?[*]const u8, n: usize, call: u64) ?[*]u8 {
    _ = call;
    return run(obj, args, n, struct {
        fn body(arena: Allocator, w: *Writer, h: u64, a: *Reader) Error!void {
            _ = arena;
            _ = h;
            _ = a;
            const v: Echo = try impl.makeEcho();
            w.uint(try retain(.{ .Echo = v }));
        }
    }.body);
}

export fn mygo_roundtrip_Echo_Scalars(obj: u64, args: ?[*]const u8, n: usize, call: u64) ?[*]u8 {
    _ = call;
    return run(obj, args, n, struct {
        fn body(arena: Allocator, w: *Writer, h: u64, a: *Reader) Error!void {
            const o = try objEcho(h);
            const p0 = try a.int();
            const p1 = @as(i8, @truncate(try a.int()));
            const p2 = @as(u16, @truncate(try a.uint()));
            const p3 = @as(i32, @truncate(try a.int()));
            const p4 = try a.uint();
            const p5 = @as(f32, @floatCast(try a.float()));
            const p6 = try a.float();
            const p7 = try a.boolean();
            const r = o.scalars(arena, p0, p1, p2, p3, p4, p5, p6, p7);
            enc_Scalars(w, r);
        }
    }.body);
}

export fn mygo_roundtrip_Echo_Add_direct(obj: u64, p0: u64, p1: u64) u64 {
    const o = objEcho(obj) catch return 0;
